input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var projects = Array.isArray(input.projects) ? input.projects : (input.projects ? [input.projects] : []);
var excludeProjects = Array.isArray(input.excludeProjects) ? input.excludeProjects : [];
var from = input.from || 0;
var to = input.to || 0;
var userwhitelist = Array.isArray(input.userwhitelist) ? input.userwhitelist : [];

var projectNames = [];
var projectFilters = [];

for (var i = 0; i < projects.length; i++) {
  var p = projects[i];
  var name = "";
  if (typeof p === "string") {
    name = p.trim();
  } else if (typeof p === "object" && p !== null) {
    name = (p.projectname || "").trim();
  }
  if (!name) continue;
  projectNames.push(name);

  var components = (typeof p === "object" && Array.isArray(p.components)) ? p.components : [];
  var labels = (typeof p === "object" && Array.isArray(p.labels)) ? p.labels : [];

  if (components.length > 0 || labels.length > 0) {
    projectFilters.push({
      name: name,
      components: components,
      labels: labels
    });
  }
}

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  projectNames: projectNames.length > 0 ? projectNames : ["__NONE__"],
  projectCount: projectNames.length,
  excludeProjects: excludeProjects.length > 0 ? excludeProjects : ["__NONE__"],
  excludeCount: excludeProjects.length,
  projectFilters: JSON.stringify(projectFilters),
  from: from,
  to: to,
  hasFrom: from ? 1 : 0,
  hasTo: to ? 1 : 0,
  userwhitelist: userwhitelist.length > 0 ? userwhitelist : ["__NONE__"],
  hasUserwhitelist: userwhitelist.length > 0 ? 1 : 0
})

output_script:
var issues = results.main || [];
var fromTs = input.from || 0;
var toTs = input.to || 0;
var startDate = fromTs ? new Date(fromTs * 1000) : null;
var endDate = toTs ? new Date(toTs * 1000) : null;
var projectFilters = JSON.parse(input.projectFilters || "[]");

var filtersByProject = {};
for (var fi = 0; fi < projectFilters.length; fi++) {
  filtersByProject[projectFilters[fi].name] = projectFilters[fi];
}

function passesProjectFilter(issue) {
  var filter = filtersByProject[issue.original_project];
  if (!filter) return true;
  var comps = filter.components || [];
  var lbls = filter.labels || [];
  if (comps.length === 0 && lbls.length === 0) return true;

  if (comps.length > 0) {
    var comp = issue.component || "";
    for (var c = 0; c < comps.length; c++) {
      if (comp.indexOf(comps[c]) >= 0) return true;
    }
  }

  if (lbls.length > 0) {
    var issueLabelStr = issue.labels || "";
    var issueLabels = issueLabelStr ? issueLabelStr.split(",") : [];
    for (var l = 0; l < lbls.length; l++) {
      for (var il = 0; il < issueLabels.length; il++) {
        if (issueLabels[il].trim() === lbls[l]) return true;
      }
    }
  }

  return false;
}

var createdByDay = {};
var completedByDay = {};
var idx, issue, cd, rd, dayStr;

for (idx = 0; idx < issues.length; idx++) {
  issue = issues[idx];
  if (!passesProjectFilter(issue)) continue;

  if (issue.created_date) {
    cd = new Date(issue.created_date);
    if (!isNaN(cd.getTime())) {
      if ((!startDate || cd >= startDate) && (!endDate || cd <= endDate)) {
        dayStr = cd.toISOString().split("T")[0];
        createdByDay[dayStr] = (createdByDay[dayStr] || 0) + 1;
      }
    }
  }

  if (issue.resolution_date) {
    rd = new Date(issue.resolution_date);
    if (!isNaN(rd.getTime())) {
      if ((!startDate || rd >= startDate) && (!endDate || rd <= endDate)) {
        dayStr = rd.toISOString().split("T")[0];
        completedByDay[dayStr] = (completedByDay[dayStr] || 0) + 1;
      }
    }
  }
}

var allDaysSet = {};
var key;
for (key in createdByDay) {
  if (createdByDay.hasOwnProperty(key)) allDaysSet[key] = true;
}
for (key in completedByDay) {
  if (completedByDay.hasOwnProperty(key)) allDaysSet[key] = true;
}

var sortedDays = [];
for (key in allDaysSet) {
  if (allDaysSet.hasOwnProperty(key)) sortedDays.push(key);
}
sortedDays.sort();

var output;

if (sortedDays.length === 0) {
  output = {
    type: "line",
    label: "Issue Throughput",
    description: "No data available.",
    data: { labels: [], datasets: [] }
  };
} else {
  var firstDay = new Date(sortedDays[0] + "T00:00:00");
  var lastDay = new Date(sortedDays[sortedDays.length - 1] + "T00:00:00");

  var allDates = [];
  var d = new Date(firstDay.getTime());
  while (d <= lastDay) {
    allDates.push(d.toISOString().split("T")[0]);
    d.setDate(d.getDate() + 1);
  }

  var chartLabels = [];
  var cumCreated = [];
  var cumCompleted = [];
  var runCreated = 0;
  var runCompleted = 0;
  var dailyCreated = [];
  var dailyCompleted = [];
  var backlogDelta = [];

  for (var j = 0; j < allDates.length; j++) {
    var day = allDates[j];
    chartLabels.push(day);
    var dc = createdByDay[day] || 0;
    var dd = completedByDay[day] || 0;
    runCreated += dc;
    runCompleted += dd;
    cumCreated.push(runCreated);
    cumCompleted.push(runCompleted);
    dailyCreated.push(dc);
    dailyCompleted.push(dd);
    backlogDelta.push(runCreated - runCompleted);
  }

  output = {
    type: "line",
    label: "Issue Throughput",
    description: "Cumulative Created vs Closed issues over time. The gap between the lines represents the backlog delta for the selected period.",
    data: {
      labels: chartLabels,
      datasets: [
        {
          label: "Cumulative Closed",
          data: cumCompleted,
          borderColor: "rgba(75, 192, 192, 1)",
          backgroundColor: "transparent",
          borderWidth: 2.5,
          pointRadius: 0,
          fill: false,
          tension: 0.3,
          order: 2
        },
        {
          label: "Cumulative Created",
          data: cumCreated,
          borderColor: "rgba(255, 99, 132, 1)",
          backgroundColor: "rgba(255, 99, 132, 0.15)",
          borderWidth: 2.5,
          pointRadius: 0,
          fill: "-1",
          tension: 0.3,
          order: 1
        }
      ],
      backlogDelta: backlogDelta,
      dailyCreated: dailyCreated,
      dailyCompleted: dailyCompleted,
      options: {
        scales: {
          x: {
            grid: { display: false }
          },
          y: {
            beginAtZero: true,
            title: { display: true, text: "Total issues" },
            grid: { color: "rgba(0, 0, 0, 0.1)" }
          }
        },
        plugins: {
          legend: {
            display: true,
            labels: {
              usePointStyle: true,
              pointStyle: "circle",
              padding: 15
            }
          },
          tooltip: {
            mode: "index",
            intersect: false
          }
        },
        interaction: {
          mode: "index",
          intersect: false
        }
      }
    }
  };
}

(output)
